<?php

namespace Modules\Production\Services;

use Illuminate\Support\Facades\DB;use Modules\Core\Approval\ApprovalEngine;use Modules\Core\Models\User;use Modules\Core\Services\AuditService;use Modules\Core\Services\NumberingService;use Modules\Inventory\Models\StockBalance;use Modules\Inventory\Models\StockReservation;use Modules\ProductDev\Models\Bom;use Modules\ProductDev\Models\Routing;use Modules\Production\Models\ProductionOrder;use Modules\Sales\Models\SalesOrder;use RuntimeException;
class ProductionOrderService
{
 public function __construct(private NumberingService$numbering,private ApprovalEngine$approval,private AuditService$audit,private StandardCostSnapshotService$costSnapshots){}
 public function createFromSalesOrder(SalesOrder$so,User$creator):array{return DB::transaction(function()use($so,$creator){$lockedSo=SalesOrder::withoutGlobalScopes()->with('lines')->whereKey($so->id)->lockForUpdate()->firstOrFail();$this->access($creator,(int)$lockedSo->company_id);if($lockedSo->status!=='CONFIRMED')throw new RuntimeException('MO hanya bisa dibuat dari SO CONFIRMED (BR-023).');$mos=[];$qtys=$lockedSo->lines->groupBy('style_id')->map(fn($x)=>$x->sum(fn($l)=>(float)$l->qty));foreach($qtys as$styleId=>$qty){if(ProductionOrder::withoutGlobalScopes()->where('company_id',$lockedSo->company_id)->where('sales_order_id',$lockedSo->id)->where('style_id',$styleId)->exists())continue;$bom=Bom::where('style_id',$styleId)->first()?->approvedVersion();$routing=Routing::where('style_id',$styleId)->first()?->approvedVersion();if(!$bom||!$routing)throw new RuntimeException("Style #{$styleId} belum punya BOM/Routing APPROVED (BR-023).");$mo=ProductionOrder::create(['company_id'=>$lockedSo->company_id,'doc_no'=>$this->numbering->next($lockedSo->company_id,'MO'),'sales_order_id'=>$lockedSo->id,'style_id'=>$styleId,'bom_version_id'=>$bom->id,'routing_version_id'=>$routing->id,'qty_planned'=>$qty,'status'=>'PLANNED','created_by'=>$creator->id]);$mos[]=$this->costSnapshots->attachIfAvailable($mo); }if($mos===[])throw new RuntimeException('Semua style di SO ini sudah punya MO.');$this->audit->record('create','production_orders',after:['sales_order'=>$lockedSo->doc_no,'mo_count'=>count($mos),'standard_cost_snapshots'=>collect($mos)->whereNotNull('standard_cost_snapshot_hash')->count()]);return$mos;});}
 public function release(ProductionOrder$mo,int$warehouseId,User$user):ProductionOrder{return DB::transaction(function()use($mo,$warehouseId,$user){$locked=ProductionOrder::withoutGlobalScopes()->with('bomVersion.lines.material')->whereKey($mo->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$locked->company_id);if($locked->status!=='PLANNED')throw new RuntimeException('Hanya MO PLANNED yang bisa di-release.');$locked=$this->costSnapshots->requireForRelease($locked)->load('bomVersion.lines.material');if(!DB::table('warehouses')->where('id',$warehouseId)->where('company_id',$locked->company_id)->exists())throw new RuntimeException('Warehouse tidak ditemukan pada company MO.');if(StockReservation::withoutGlobalScopes()->where('mo_id',$locked->id)->whereIn('status',['ACTIVE','PARTIAL_ISSUED'])->exists())throw new RuntimeException('MO masih memiliki reservasi aktif.');$needs=[];foreach($locked->bomVersion->lines as$b){$id=(int)$b->material_id;$needs[$id]??=['required'=>0.0,'backflush'=>true,'material'=>$b->material];$needs[$id]['required']+=$b->grossPerPcs()*(float)$locked->qty_planned;$needs[$id]['backflush']=$needs[$id]['backflush']&&(bool)$b->is_backflush;}$plans=[];$short=[];foreach($needs as$id=>$need){$required=round($need['required'],4);$remaining=$required;$balances=StockBalance::withoutGlobalScopes()->where('company_id',$locked->company_id)->where('material_id',$id)->where('warehouse_id',$warehouseId)->whereRaw('on_hand > reserved + quality_hold')->orderBy('id')->lockForUpdate()->get();foreach($balances as$balance){$available=max(0,$balance->available());if($available<=0||$remaining<=0)continue;$qty=min($available,$remaining);$plans[]=['material_id'=>$id,'balance'=>$balance,'qty'=>$qty];$remaining=round($remaining-$qty,4);}if($remaining>0.0001){$m=$need['material'];$short[]=sprintf('%s (%s): butuh %s, available %s, kurang %s',$m->code,$m->name,rtrim(rtrim(number_format($required,4),'0'),'.'),rtrim(rtrim(number_format($required-$remaining,4),'0'),'.'),rtrim(rtrim(number_format($remaining,4),'0'),'.'));}}if($short!==[])throw new RuntimeException('BR-040: material shortage saat release MO:\n- '.implode("\n- ",$short));foreach($plans as$p){$b=$p['balance'];StockReservation::create(['company_id'=>$locked->company_id,'mo_id'=>$locked->id,'material_id'=>$p['material_id'],'warehouse_id'=>$warehouseId,'location_id'=>$b->location_id,'lot_no'=>$b->lot_no,'roll_id'=>$b->roll_id,'ownership'=>$b->ownership,'qty_reserved'=>$p['qty'],'status'=>'ACTIVE','created_by'=>$user->id]);$b->reserved=(float)$b->reserved+$p['qty'];$b->save();}foreach($needs as$id=>$need){$required=round($need['required'],4);$locked->materialAllocations()->updateOrCreate(['material_id'=>$id],['qty_required'=>$required,'qty_reserved'=>$required,'qty_issued'=>0,'is_backflush'=>$need['backflush']]);}$locked->update(['status'=>'RELEASED','updated_by'=>$user->id]);$this->audit->record('update',$locked,after:['status'=>'RELEASED','reservations'=>count($plans),'standard_cost_sheet_id'=>$locked->standard_cost_sheet_id,'snapshot_hash'=>$locked->standard_cost_snapshot_hash]);return$locked->fresh('materialAllocations');});}
 public function unrelease(ProductionOrder$mo,User$user):ProductionOrder{return DB::transaction(function()use($mo,$user){$locked=ProductionOrder::withoutGlobalScopes()->whereKey($mo->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$locked->company_id);if($locked->status!=='RELEASED')throw new RuntimeException('Hanya MO RELEASED yang bisa di-unrelease.');$reservations=StockReservation::withoutGlobalScopes()->where('mo_id',$locked->id)->whereIn('status',['ACTIVE','PARTIAL_ISSUED'])->lockForUpdate()->get();if($reservations->contains(fn($r)=>(float)$r->qty_issued>0))throw new RuntimeException('MO yang sudah memiliki material issue tidak dapat di-unrelease.');foreach($reservations as$r){$remaining=$r->remaining();if($remaining<=0)continue;$b=StockBalance::withoutGlobalScopes()->where('company_id',$locked->company_id)->where('material_id',$r->material_id)->where('warehouse_id',$r->warehouse_id)->where('location_id',$r->location_id)->where('lot_no',$r->lot_no)->where('roll_id',$r->roll_id)->where('ownership',$r->ownership)->lockForUpdate()->firstOrFail();if((float)$b->reserved+0.0001<$remaining)throw new RuntimeException('Saldo reserved tidak konsisten dengan reservation.');$b->reserved=(float)$b->reserved-$remaining;$b->save();$r->update(['status'=>'RELEASED']);}$locked->materialAllocations()->update(['qty_reserved'=>0]);$locked->update(['status'=>'PLANNED','updated_by'=>$user->id]);$this->costSnapshots->verify($locked->fresh());$this->audit->record('update',$locked,after:['status'=>'PLANNED','released_reservations'=>$reservations->count(),'standard_cost_retained'=>true]);return$locked->fresh();});}
 public function submit(ProductionOrder$mo,User$u):void{$this->approval->submit($mo,'MO',$u);}private function access(User$u,int$c):void{if((int)$u->company_id!==$c&&!$u->companies()->whereKey($c)->exists())throw new RuntimeException('User tidak memiliki akses ke company MO.');}
}
